  IF NOT ((SELECT COUNT(*) FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'436f6d6261743a4e696768746361704865726f69634d656c65655363616c696e67' USING utf8mb4))=1 AND NOT EXISTS (SELECT 1 FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'436f6d6261743a4e696768746361704865726f69634d656c65655363616c696e67' USING utf8mb4) AND NOT ((`ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'436f6d6261743a4e696768746361704865726f69634d656c65655363616c696e67' USING utf8mb4) AND BINARY `rule_value` <=> BINARY CONVERT(X'66616c7365' USING utf8mb4) AND BINARY `notes` <=> BINARY CONVERT(X'52657669657765642057504d206865726f69632d737472656e67746820776561706f6e2d6869742063757276653b2072657175697265732070616972656420776f726c6420616e64207a6f6e652e' USING utf8mb4))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='WPM rule_values preimage drift'; END IF;
  UPDATE rule_values SET `rule_value`=CONVERT(X'74727565' USING utf8mb4) WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'436f6d6261743a4e696768746361704865726f69634d656c65655363616c696e67' USING utf8mb4);
  IF NOT ((SELECT COUNT(*) FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'436f6d6261743a4e696768746361704865726f69634d656c65655363616c696e67' USING utf8mb4))=1 AND NOT EXISTS (SELECT 1 FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'436f6d6261743a4e696768746361704865726f69634d656c65655363616c696e67' USING utf8mb4) AND NOT ((`ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'436f6d6261743a4e696768746361704865726f69634d656c65655363616c696e67' USING utf8mb4) AND BINARY `rule_value` <=> BINARY CONVERT(X'74727565' USING utf8mb4) AND BINARY `notes` <=> BINARY CONVERT(X'52657669657765642057504d206865726f69632d737472656e67746820776561706f6e2d6869742063757276653b2072657175697265732070616972656420776f726c6420616e64207a6f6e652e' USING utf8mb4))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='WPM rule_values afterimage mismatch'; END IF;
